import math
from numbers import Real


class BlockCompactor:
    class Block:
        def __init__(self, start, end):
            if any(isinstance(v, bool) or not isinstance(v, Real) for v in (start, end)):
                raise TypeError("endpoints must be real numbers")
            if not math.isfinite(start) or not math.isfinite(end) or start > end:
                raise ValueError("invalid block endpoints")
            self.start = start
            self.end = end

    @staticmethod
    def merge(blocks, join_touching=False):
        if not isinstance(join_touching, bool):
            raise TypeError("join_touching must be boolean")
        try:
            items = list(blocks)
        except TypeError as exc:
            raise TypeError("blocks must be iterable") from exc
        if any(not isinstance(item, BlockCompactor.Block) for item in items):
            raise TypeError("blocks must contain Block instances")
        ordered = sorted(items, key=lambda item: (item.start, item.end))
        result = []
        for item in ordered:
            if not result:
                result.append(BlockCompactor.Block(item.start, item.end))
                continue
            previous = result[-1]
            overlaps = item.start <= previous.end and item.start < item.end
            touches = item.start == previous.end
            if overlaps or (join_touching and touches):
                previous.end = max(previous.end, item.end)
            else:
                result.append(BlockCompactor.Block(item.start, item.end))
        return result

